"use client";
import type { ReactNode } from "react";
import "./shimmer-text.css";

/** Status text with a slow highlight passing through it. Announced politely. */
export function ShimmerText({
  children,
  className = "",
}: {
  children: ReactNode;
  className?: string;
}) {
  return (
    <span role="status" className={`forme-shimmer ${className}`}>
      {children}
    </span>
  );
}

.forme-shimmer {
  --forme-shimmer-base: #71717a;
  --forme-shimmer-light: #fafafa;
  display: inline-block;
  background: linear-gradient(
    100deg,
    var(--forme-shimmer-base) 40%,
    var(--forme-shimmer-light) 50%,
    var(--forme-shimmer-base) 60%
  );
  background-size: 250% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: forme-shimmer-pass 2.6s linear infinite;
}
@keyframes forme-shimmer-pass {
  from {
    background-position: 125% 0;
  }
  to {
    background-position: -125% 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .forme-shimmer {
    animation: none;
    background: none;
    color: var(--forme-shimmer-light);
  }
}
